window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-34c94208592e32c2"]={"versions": [{"id": "FIG-34c94208592e32c2", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Einzelschritts „Increment Counter“ innerhalb der AUTOSAR-E2E-Bibliothek (End-to-End Communication Protection), spezifisch für das Profil 4m (<code>E2E Profile 4m</code>). Das Diagramm modelliert die interne Ausführungslogik der Schutz- und Weiterleitungsfunktionen <code>E2E_P04mProtect()</code> und <code>E2E_P04mForward()</code> auf Ebene der Software-Funktionsabläufe.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitätsknoten (Aktion):</strong> <code>State-&gt;Counter++</code> repräsentiert die Modifikation des Sequenzzählers in der Zustandsstruktur.\n</li><li><strong>Funktionskontext (Aufrufer):</strong> Symbole am oberen linken Rand indizieren die Zuordnung zu den C-Schnittstellenfunktionen <code>E2E_P04mProtect()</code> und <code>E2E_P04mForward()</code>.\n</li><li><strong>Datenstruktur &amp; Schnittstelle:</strong> Zeigerzugriff auf das Member <code>Counter</code> der Datenstruktur <code>State</code> (Typ <code>E2E_P04mProtectStateType</code> bzw. äquivalente Profil-4m-Zustandsstruktur).\n</li><li><strong>Kommentar/Notiz:</strong> Assoziierte UML-Note mit der Spezifikation: „The type is uint16. After 0xFF&#x27;FF, the next value is 0.“.\n</li><li><strong>Kontrollflussknoten:</strong> Initialknoten (ausgefüllter Kreis) und Endknoten (Aktivitätsendknoten als Kreis mit innerem ausgefüllten Punkt).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Kontrollfluss startet am Initialknoten und verzweigt ohne Bedingungen direkt auf die Aktion <code>State-&gt;Counter++</code>. Nach Ausführung des Inkrements geht der Ablauf unmittelbar in den Aktivitätsendknoten über. Die Operation erfolgt atomar als ein einzelner Schritt innerhalb des übergeordneten Protect- bzw. Forward-Ablaufs.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ vorgeschrieben durch Anforderung <code>[PRS_E2E_00767]</code>. Implementierende Entwickler müssen sicherstellen:</p>\n<ul class=\"fig-list\"><li>Der Zähler <code>Counter</code> ist vom Datentyp <code>uint16</code> (Wertebereich 0 bis 65535 bzw. <code>0xFFFF</code>).\n</li><li>Das Überlaufverhalten ist strikt modulo-basiert: Nach Erreichen des Maximalwerts <code>0xFFFF</code> muss der Folgewert zwingend wieder auf <code>0</code> übergehen (arithmetischer Wrap-around ohne Exception/Sättigung).\n</li><li>Die Operation muss konsistent in beiden Funktionsausprägungen <code>E2E_P04mProtect</code> und <code>E2E_P04mForward</code> ausgeführt werden.\n</li></ul>"}, {"id": "FIG-ac3f8349d7e28f9b", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Einzelschritts „Increment Counter“ innerhalb der AUTOSAR-E2E-Bibliothek (End-to-End Communication Protection), spezifisch für das Profil 4m (<code>E2E Profile 4m</code>). Das Diagramm modelliert die interne Ausführungslogik der Schutz- und Weiterleitungsfunktionen <code>E2E_P04mProtect()</code> und <code>E2E_P04mForward()</code> auf Ebene der Software-Funktionsabläufe.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitätsknoten (Aktion):</strong> <code>State-&gt;Counter++</code> repräsentiert die Modifikation des Sequenzzählers in der Zustandsstruktur.\n</li><li><strong>Funktionskontext (Aufrufer):</strong> Symbole am oberen linken Rand indizieren die Zuordnung zu den C-Schnittstellenfunktionen <code>E2E_P04mProtect()</code> und <code>E2E_P04mForward()</code>.\n</li><li><strong>Datenstruktur &amp; Schnittstelle:</strong> Zeigerzugriff auf das Member <code>Counter</code> der Datenstruktur <code>State</code> (Typ <code>E2E_P04mProtectStateType</code> bzw. äquivalente Profil-4m-Zustandsstruktur).\n</li><li><strong>Kommentar/Notiz:</strong> Assoziierte UML-Note mit der Spezifikation: „The type is uint16. After 0xFF&#x27;FF, the next value is 0.“.\n</li><li><strong>Kontrollflussknoten:</strong> Initialknoten (ausgefüllter Kreis) und Endknoten (Aktivitätsendknoten als Kreis mit innerem ausgefüllten Punkt).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Kontrollfluss startet am Initialknoten und verzweigt ohne Bedingungen direkt auf die Aktion <code>State-&gt;Counter++</code>. Nach Ausführung des Inkrements geht der Ablauf unmittelbar in den Aktivitätsendknoten über. Die Operation erfolgt atomar als ein einzelner Schritt innerhalb des übergeordneten Protect- bzw. Forward-Ablaufs.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ vorgeschrieben durch Anforderung <code>[PRS_E2E_00767]</code>. Implementierende Entwickler müssen sicherstellen:</p>\n<ul class=\"fig-list\"><li>Der Zähler <code>Counter</code> ist vom Datentyp <code>uint16</code> (Wertebereich 0 bis 65535 bzw. <code>0xFFFF</code>).\n</li><li>Das Überlaufverhalten ist strikt modulo-basiert: Nach Erreichen des Maximalwerts <code>0xFFFF</code> muss der Folgewert zwingend wieder auf <code>0</code> übergehen (arithmetischer Wrap-around ohne Exception/Sättigung).\n</li><li>Die Operation muss konsistent in beiden Funktionsausprägungen <code>E2E_P04mProtect</code> und <code>E2E_P04mForward</code> ausgeführt werden.\n</li></ul>"}], "trans": [{"from": "FIG-34c94208592e32c2", "to": "FIG-ac3f8349d7e28f9b", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
